'use strict';
// App assets only. Personal training data never enters a request or a cache key.
const VERSION='repclub-offline-20261011-2';
const PREFIX='repclub-offline-';
const SCOPE=self.registration.scope;
const absolute=path=>new URL(path,SCOPE).href;
const STATUS=absolute('__repclub_offline_status__');
const CORE=['index.html','style.css','app.js','install.js','exercise-data.js','exercise-sources.json','manifest.webmanifest','icon.svg','icon-192.png','icon-512.png','fonts/sans-regular.woff','fonts/sans-bold.woff','fonts/display.woff','image-assets.json'];
let preparing=null;
async function announce(data){const clients=await self.clients.matchAll({type:'window',includeUncontrolled:true});for(const client of clients)client.postMessage(data)}
async function loadAsset(path,cache){const url=absolute(path);const response=await fetch(url,{credentials:'same-origin',cache:'reload'});if(!response.ok||response.redirected)throw new Error('Asset unavailable: '+path);const type=response.headers.get('content-type')||'';if(path!=='index.html'&&type.includes('text/html'))throw new Error('Unexpected HTML response: '+path);await cache.put(url,response)}
self.addEventListener('install',event=>{event.waitUntil((async()=>{const cache=await caches.open(VERSION);for(const path of CORE)await loadAsset(path,cache)})())});
self.addEventListener('activate',event=>{event.waitUntil((async()=>{await self.clients.claim();for(const key of await caches.keys())if(key.startsWith(PREFIX)&&key!==VERSION)await caches.delete(key);await announce({type:'UPDATE_ACTIVATED'})})())});
async function offlineStatus(){const cache=await caches.open(VERSION);const response=await cache.match(absolute('image-assets.json'));const paths=response?await response.json():[];let done=0;for(const path of paths)if(await cache.match(absolute(path)))done++;let coreReady=true;for(const path of CORE)if(!await cache.match(absolute(path)))coreReady=false;return{type:'OFFLINE_PROGRESS',done,total:paths.length,complete:coreReady&&Boolean(response)&&done===paths.length}}
async function prepare(){const cache=await caches.open(VERSION),response=await cache.match(absolute('image-assets.json'));if(!response)throw new Error('Image manifest unavailable');const paths=await response.json();await cache.delete(STATUS);let done=0;const missing=[];for(const path of paths){if(await cache.match(absolute(path)))done++;else missing.push(path)}await announce({type:'OFFLINE_PROGRESS',done,total:paths.length,complete:false});let index=0,errors=0;async function worker(){while(index<missing.length){const path=missing[index++];try{await loadAsset(path,cache);done++;if(done%10===0||done===paths.length)await announce({type:'OFFLINE_PROGRESS',done,total:paths.length,complete:false})}catch{errors++}}}await Promise.all(Array.from({length:4},worker));const result={type:'OFFLINE_PROGRESS',done,total:paths.length,complete:errors===0&&done===paths.length};if(result.complete)await cache.put(STATUS,new Response(JSON.stringify(result),{headers:{'content-type':'application/json'}}));await announce(result);if(errors)await announce({type:'OFFLINE_ERROR',failed:errors})}
self.addEventListener('message',event=>{if(event.data?.type==='GET_OFFLINE_STATUS')event.waitUntil(offlineStatus().then(data=>event.source?.postMessage(data)).catch(()=>event.source?.postMessage({type:'OFFLINE_ERROR'})));if(event.data?.type==='PREPARE_OFFLINE'){if(!preparing)preparing=prepare().catch(()=>announce({type:'OFFLINE_ERROR'})).finally(()=>{preparing=null});event.waitUntil(preparing)}if(event.data?.type==='ACTIVATE_UPDATE')event.waitUntil(self.skipWaiting())});
self.addEventListener('fetch',event=>{const request=event.request,url=new URL(request.url);if(request.method!=='GET'||url.origin!==self.location.origin)return;const shellPaths=[new URL(SCOPE).pathname,new URL('index.html',SCOPE).pathname];if(request.mode==='navigate'&&shellPaths.includes(url.pathname)){event.respondWith((async()=>{const cache=await caches.open(VERSION),shell=await cache.match(absolute('index.html'));if(shell)return shell;try{return await fetch(request)}catch{return new Response('Open Repclub online once to finish setting up offline access.',{status:503,headers:{'content-type':'text/plain; charset=utf-8'}})}})());return}const localPath=url.pathname.slice(new URL(SCOPE).pathname.length);if(!CORE.includes(localPath)&&!localPath.startsWith('exercise-images/'))return;event.respondWith((async()=>{const cache=await caches.open(VERSION),saved=await cache.match(url.href);if(saved)return saved;try{const response=await fetch(request);if(response.ok&&!response.redirected&&!(response.headers.get('content-type')||'').includes('text/html'))await cache.put(url.href,response.clone());return response}catch{return new Response('Asset not downloaded yet. Reconnect and use Download for offline in Preferences.',{status:503,headers:{'content-type':'text/plain; charset=utf-8'}})}})())});
